onRowSelected:
{{
  (function() {
    const row = Table_interventions_perso.selectedRow;
    if (!row || row.isHeader === true) return;

    // 1. Si intervention liée : redirection vers la fiche d'intervention
    if (row.ID_Intervention) {
      return storeValue('tab_atelier_actif', Tabs1.selectedTab)
        .then(() => storeValue('page_precedente', '🛠️ Atelier'))
        .then(() => navigateTo('Détail Intervention', { id: row.ID_Intervention }));
    }

    // 2. Si tâche planifiée seule : mémorisation et ouverture de la modale
    if (row.ID_Creneau) {
      return storeValue('selected_creneau_id', row.ID_Creneau)
        .then(() => Get_Creneau_Detail.run())
        .then(() => showModal('modal_detail_creneau'));
    }
  })()
}}

