tableData:
{{
  (() => {
    const data = Get_Atelier_Perso.data || [];
    let groupedData = [];

    let counts = {};
    data.forEach(row => {
       let st = row.Statut || "Non défini";
       counts[st] = (counts[st] || 0) + 1;
    });

    let currentStatut = null;
    data.forEach((row) => {
      let st = row.Statut || "Non défini";

      if (st !== currentStatut) {
        let emoji = "🔽";
        const cleanSt = st.toUpperCase().replace(/^[^A-ZÀ-Ÿ0-9]+/, '').trim();

        switch (cleanSt) {
          case 'CRÉNEAU IMMINENT':
          case 'CRENEAU IMMINENT': emoji = '⚡'; break;
          case 'CRÉNEAU PLANIFIÉ':
          case 'CRENEAU PLANIFIE': emoji = '📅'; break;
          case 'ACTION REQUISE': emoji = '⚠️'; break;
          case 'À VÉRIFIER': emoji = '👁️'; break;
          case 'PIECE A COMMANDER': emoji = '🛒'; break;
          case 'DEVIS': emoji = '📋'; break;
          case 'EN COURS': emoji = '🛠️'; break;
          case 'EN TEST': emoji = '🧪'; break;
          case 'H.S.':
          case 'HS': emoji = '🚫'; break;
          case 'TAST':
          case 'À DIAGNOSTIQUER': emoji = '🔍'; break;
          case 'A REMONTER': emoji = '🔨'; break;
          case 'ATTENTE CLIENT': emoji = '👨‍💼'; break;
          case 'PIECE EN COMMANDE': emoji = '🚚'; break;
          case 'PRÊT': emoji = '✅'; break;
        }

        const cleanLabel = st.replace(/^[⚡📅⚠️🚫👁️🛒📋🛠️🧪🔍🔨👨‍💼🚚✅\s]+/, '').trim();

        groupedData.push({
          isHeader: true,
          OriginalStatut: st,
          Client_Affichage: `${emoji} ${cleanLabel} (${counts[st]})`, 
          Statut: "", 
          Machine: "",
          "N° OR": "",
          Date_Entree: "",
          ID_Intervention: null,
          ID_Creneau: null
        });
        currentStatut = st;
      }

      groupedData.push({ ...row, isHeader: false });
    });

    return groupedData;
  })()
}}
